"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import LanguageSwitcher from "./LanguageSwitcher";
import { useTranslations } from "next-intl";

export default function Navbar() {
  const pathname = usePathname();
  const locale = pathname.split("/")[1]; // "en" or "es"
  const t = useTranslations("nav");

  return (
    <nav className="w-full py-6 px-8 flex justify-between items-center bg-white shadow-sm fixed top-0 left-0 z-50">
      {/* Logo */}
      <Link href={`/${locale}`} className="text-xl font-bold">
        GINKGO
      </Link>

      {/* Links */}
      <div className="flex gap-8 text-gray-700">
        <Link href={`/${locale}`} className="hover:text-black">
          {t("home")}
        </Link>

        <Link href={`/${locale}/opportunities`} className="hover:text-black">
          {t("opportunities")}
        </Link>

        <Link href={`/${locale}/regions`} className="hover:text-black">
          {t("regions")}
        </Link>

        <Link href={`/${locale}/services`} className="hover:text-black">
          {t("services")}
        </Link>

        <Link href={`/${locale}/process`} className="hover:text-black">
          {t("process")}
        </Link>

        <Link href={`/${locale}/contact`} className="hover:text-black">
          {t("contact")}
        </Link>
      </div>

      {/* Language Switcher */}
      <LanguageSwitcher />
    </nav>
  );
}
