"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";

export default function LanguageSwitcher() {
  const pathname = usePathname();

  // Extract current locale
  const currentLocale = pathname.split("/")[1]; // "en" or "es"

  // Build the same path but with the other locale
  const otherLocale = currentLocale === "en" ? "es" : "en";
  const newPath = "/" + otherLocale + pathname.substring(3);

  return (
    <div className="flex gap-2 items-center">
      <Link
        href={newPath}
        className="px-3 py-1 border rounded-full text-sm hover:bg-gray-100"
      >
        {otherLocale.toUpperCase()}
      </Link>
    </div>
  );
}
